1	using System;
2	using System.Diagnostics;
3	using System.IO;
4	using System.Runtime.InteropServices;
5	using System.Threading.Tasks;
6	using Avalonia.Controls;
7	using Avalonia.Input;
8	using Avalonia.Interactivity;
9	using CcDirector.Core.Browsers;
10	using CcDirector.Core.Utilities;
11	
12	namespace CcDirector.Terminal.Avalonia;
13	
14	/// <summary>
15	/// Inputs the shared link context menu needs to build and act on its items. The owner is any visual
16	/// in the live tree (used to reach the clipboard and to host browser-launch errors); the callbacks
17	/// let each caller route "View File" and browser-launch failures into its own surface.
18	/// </summary>
19	public sealed class LinkMenuContext
20	{
21	    /// <summary>The detected link text (a path or a URL), exactly as <see cref="LinkDetector"/> returned it.</summary>
22	    public required string Link { get; init; }
23	
24	    /// <summary>Whether <see cref="Link"/> is a file path or a URL.</summary>
25	    public required LinkDetector.LinkType Type { get; init; }
26	
27	    /// <summary>Repo root for resolving relative paths, or null.</summary>
28	    public string? RepoPath { get; init; }
29	
30	    /// <summary>A visual in the live tree, used to reach the clipboard.</summary>
31	    public required Control Owner { get; init; }
32	
33	    /// <summary>Called with the resolved absolute path when the user picks "View File".</summary>
34	    public Action<string>? OnViewFile { get; init; }
35	
36	    /// <summary>Called with a human-readable message when a browser launch fails.</summary>
37	    public Action<string>? OnBrowserError { get; init; }
38	}
39	
40	/// <summary>
41	/// Builds the link context menu shared by the terminal and the History tab (GitHub #735). Both the
42	/// terminal's <c>ShowLinkContextMenu</c> and the History bubbles call this single implementation, so
43	/// a path or URL offers the exact same actions in either place - there is no divergent copy of the
44	/// menu. For a file path: View File (when viewable), Open in Browser (when HTML), Copy Path, Open in
45	/// File Manager. For a URL: Copy URL, Open in Browser (with the browser/profile submenu).
46	/// </summary>
47	public static class LinkContextMenuBuilder
48	{
49	    /// <summary>Build a fresh <see cref="ContextMenu"/> populated with the link items for this context.</summary>
50	    public static ContextMenu Build(LinkMenuContext context)
51	    {
52	        var menu = new ContextMenu();
53	        PopulateLinkItems(menu, context);
54	        return menu;
55	    }
56	
57	    /// <summary>
58	    /// Append the link items to an existing menu. The terminal uses this so it can add its own paste
59	    /// items after the shared link items; a standalone caller can use <see cref="Build"/> instead.
60	    /// </summary>
61	    public static void PopulateLinkItems(ContextMenu menu, LinkMenuContext context)
62	    {
63	        ArgumentNullException.ThrowIfNull(menu);
64	        ArgumentNullException.ThrowIfNull(context);
65	
66	        if (context.Type == LinkDetector.LinkType.Path)
67	        {
68	            bool addedViewerItem = false;
69	
70	            if (FileExtensions.IsViewable(context.Link))
71	            {
72	                var viewItem = new MenuItem { Header = "View File" };
73	                viewItem.Click += (_, _) => OpenFileViewer(context);
74	                menu.Items.Add(viewItem);
75	                addedViewerItem = true;
76	            }
77	
78	            if (FileExtensions.IsHtml(context.Link))
79	            {
80	                string htmlTarget = ResolvePath(context, context.Link).Replace('/', '\\').TrimEnd('\\');
81	                menu.Items.Add(BuildOpenInBrowserMenuItem(menu, context, htmlTarget));
82	                addedViewerItem = true;
83	            }
84	
85	            if (addedViewerItem)
86	                menu.Items.Add(new Separator());
87	
88	            var copyItem = new MenuItem { Header = "Copy Path" };
89	            copyItem.Click += (_, _) => _ = CopyLinkToClipboardAsync(context);
90	            menu.Items.Add(copyItem);
91	
92	            var explorerItem = new MenuItem { Header = "Open in File Manager" };
93	            explorerItem.Click += (_, _) => OpenInFileManager(context);
94	            menu.Items.Add(explorerItem);
95	        }
96	        else if (context.Type == LinkDetector.LinkType.Url)
97	        {
98	            var copyItem = new MenuItem { Header = "Copy URL" };
99	            copyItem.Click += (_, _) => _ = CopyLinkToClipboardAsync(context);
100	            menu.Items.Add(copyItem);
101	
102	            menu.Items.Add(BuildOpenInBrowserMenuItem(menu, context, context.Link));
103	        }
104	    }
105	
106	    private static async Task CopyLinkToClipboardAsync(LinkMenuContext context)
107	    {
108	        if (string.IsNullOrEmpty(context.Link))
109	            return;
110	
111	        string textToCopy = context.Type == LinkDetector.LinkType.Path
112	            ? ResolvePath(context, context.Link).Replace('/', '\\').TrimEnd('\\')
113	            : context.Link;
114	
115	        var clipboard = TopLevel.GetTopLevel(context.Owner)?.Clipboard;
116	        if (clipboard != null)
117	        {
118	            await clipboard.SetTextAsync(textToCopy);
119	            FileLog.Write($"[LinkContextMenuBuilder] Copied link: {textToCopy}");
120	        }
121	    }
122	
123	    private static void OpenInFileManager(LinkMenuContext context)
124	    {
125	        if (string.IsNullOrEmpty(context.Link))
126	            return;
127	
128	        try
129	        {
130	            string path = ResolvePath(context, context.Link).Replace('/', '\\').TrimEnd('\\');
131	            string target = File.Exists(path) ? Path.GetDirectoryName(path) ?? path : path;
132	
133	            if (RuntimeInformation.IsOSPlatform(OSPlatform.Windows))
134	                Process.Start("explorer.exe", $"\"{target}\"");
135	            else if (RuntimeInformation.IsOSPlatform(OSPlatform.OSX))
136	                Process.Start("open", $"\"{target}\"");
137	            else
138	                Process.Start("xdg-open", $"\"{target}\"");
139	
140	            FileLog.Write($"[LinkContextMenuBuilder] Opened in file manager: {target}");
141	        }
142	        catch (Exception ex)
143	        {
144	            FileLog.Write($"[LinkContextMenuBuilder] OpenInFileManager FAILED: {ex.Message}");
145	        }
146	    }
147	
148	    private static void OpenFileViewer(LinkMenuContext context)
149	    {
150	        if (string.IsNullOrEmpty(context.Link))
151	            return;
152	
153	        string path = ResolvePath(context, context.Link);
154	        FileLog.Write($"[LinkContextMenuBuilder] OpenFileViewer: {path}");
155	        context.OnViewFile?.Invoke(path);
156	    }
157	
158	    /// <summary>
159	    /// Builds the "Open in Browser" menu item for <paramref name="target"/> (a URL or a local file
160	    /// path). A plain click reopens the remembered default; hovering expands a submenu of "System
161	    /// default" plus each installed browser with its real profiles (re-read from each browser's Local
162	    /// State so newly added profiles appear without a restart).
163	    /// </summary>
164	    private static MenuItem BuildOpenInBrowserMenuItem(ContextMenu menu, LinkMenuContext context, string target)
165	    {
166	        var parent = new MenuItem { Header = "Open in Browser" };
167	
168	        // A submenu parent does NOT raise Click on its header - pressing the header just expands the
169	        // submenu. To make a plain click on the parent reopen the remembered default (while HOVER
170	        // still expands the submenu), intercept the header press in the tunnel phase. The tunnel
171	        // route also passes through this parent for presses on its OWN submenu leaves (descendants),
172	        // so launch the default ONLY when the press lands on the parent's own header rectangle.
173	        parent.AddHandler(InputElement.PointerPressedEvent, (_, e) =>
174	        {
175	            var pos = e.GetPosition(parent);
176	            bool onHeader = pos.X >= 0 && pos.Y >= 0
177	                && pos.X <= parent.Bounds.Width && pos.Y <= parent.Bounds.Height;
178	            if (!onHeader)
179	                return;
180	
181	            e.Handled = true;
182	            menu.Close();
183	            OpenInBrowserDefault(context, target);
184	        }, RoutingStrategies.Tunnel);
185	
186	        var systemItem = new MenuItem { Header = "System default" };
187	        systemItem.Click += (_, e) =>
188	        {
189	            e.Handled = true;
190	            OpenInBrowserSystemDefault(context, target);
191	        };
192	        parent.Items.Add(systemItem);
193	
194	        foreach (var browser in BrowserLauncher.DetectBrowsers())
195	        {
196	            var browserItem = new MenuItem { Header = browser.DisplayName };
197	
198	            var profiles = BrowserLauncher.GetProfiles(browser);
199	            if (profiles.Count == 0)
200	            {
201	                browserItem.Items.Add(new MenuItem { Header = "(no profiles found)", IsEnabled = false });
202	            }
203	            else
204	            {
205	                foreach (var profile in profiles)
206	                {
207	                    string header = profile.Account is null
208	                        ? profile.DisplayName
209	                        : $"{profile.DisplayName} ({profile.Account})";
210	
211	                    var profileItem = new MenuItem { Header = header };
212	                    var capturedBrowser = browser;
213	                    var capturedFolder = profile.FolderName;
214	                    profileItem.Click += (_, e) =>
215	                    {
216	                        e.Handled = true;
217	                        OpenInBrowserProfile(context, target, capturedBrowser, capturedFolder);
218	                    };
219	                    browserItem.Items.Add(profileItem);
220	                }
221	            }
222	
223	            parent.Items.Add(browserItem);
224	        }
225	
226	        return parent;
227	    }
228	
229	    private static void OpenInBrowserDefault(LinkMenuContext context, string target)
230	    {
231	        try
232	        {
233	            var remembered = BrowserDefaultStore.Load();
234	            if (remembered is null)
235	            {
236	                FileLog.Write($"[LinkContextMenuBuilder] OpenInBrowserDefault: no remembered default, using system default: {target}");
237	                BrowserLauncher.OpenSystemDefault(target);
238	                return;
239	            }
240	
241	            var browser = BrowserDefaultStore.ResolveBrowser(remembered.ExePath);
242	            BrowserLauncher.OpenWithProfile(target, browser, remembered.ProfileFolder);
243	            FileLog.Write($"[LinkContextMenuBuilder] OpenInBrowserDefault: opened {target} in {browser.DisplayName}/{remembered.ProfileFolder}");
244	        }
245	        catch (Exception ex)
246	        {
247	            FileLog.Write($"[LinkContextMenuBuilder] OpenInBrowserDefault FAILED: {ex.Message}");
248	            context.OnBrowserError?.Invoke($"Could not open in browser.\n\n{ex.Message}");
249	        }
250	    }
251	
252	    private static void OpenInBrowserSystemDefault(LinkMenuContext context, string target)
253	    {
254	        try
255	        {
256	            BrowserLauncher.OpenSystemDefault(target);
257	            FileLog.Write($"[LinkContextMenuBuilder] OpenInBrowserSystemDefault: {target}");
258	        }
259	        catch (Exception ex)
260	        {
261	            FileLog.Write($"[LinkContextMenuBuilder] OpenInBrowserSystemDefault FAILED: {ex.Message}");
262	            context.OnBrowserError?.Invoke($"Could not open in the system default browser.\n\n{ex.Message}");
263	        }
264	    }
265	
266	    private static void OpenInBrowserProfile(LinkMenuContext context, string target, BrowserInfo browser, string profileFolder)
267	    {
268	        try
269	        {
270	            BrowserLauncher.OpenWithProfile(target, browser, profileFolder);
271	            BrowserDefaultStore.Save(new BrowserDefault(browser.ExePath, profileFolder));
272	            FileLog.Write($"[LinkContextMenuBuilder] OpenInBrowserProfile: opened {target} in {browser.DisplayName}/{profileFolder}");
273	        }
274	        catch (Exception ex)
275	        {
276	            FileLog.Write($"[LinkContextMenuBuilder] OpenInBrowserProfile FAILED: {ex.Message}");
277	            context.OnBrowserError?.Invoke($"Could not open in {browser.DisplayName}.\n\n{ex.Message}");
278	        }
279	    }
280	
281	    private static string ResolvePath(LinkMenuContext context, string path)
282	        => LinkDetector.ResolvePath(path, context.RepoPath);
283	}
