8	/// <summary>
9	/// Tests for <see cref="CcDirectorConfigService"/>, the single round-trip-preserving
10	/// writer for config.json. The whole point is that a partial write must NEVER drop
11	/// sibling sections (the historical data-loss bug), so most tests assert that an
12	/// untouched block survives a targeted patch. All methods share an isolated
13	/// CC_DIRECTOR_ROOT set in the constructor; xUnit runs a class's methods sequentially.
14	/// </summary>
15	[Collection("CcStorageRoot")] // serializes all classes that mutate the process-wide CC_DIRECTOR_ROOT
16	public sealed class CcDirectorConfigServiceTests : IDisposable
17	{
18	    private readonly string _root;
19	    private readonly string? _prevRoot;
20	
21	    public CcDirectorConfigServiceTests()
22	    {
23	        _prevRoot = Environment.GetEnvironmentVariable("CC_DIRECTOR_ROOT");
24	        _root = Path.Combine(Path.GetTempPath(), "ccd-config-test-" + Guid.NewGuid().ToString("N"));
25	        Environment.SetEnvironmentVariable("CC_DIRECTOR_ROOT", _root);
26	    }
27	
28	    public void Dispose()
29	    {
30	        Environment.SetEnvironmentVariable("CC_DIRECTOR_ROOT", _prevRoot);
31	        try { if (Directory.Exists(_root)) Directory.Delete(_root, recursive: true); } catch { /* best effort */ }
32	    }
33	
34	    private static void SeedConfig(string json)
35	    {
36	        var path = CcStorage.ConfigJson();
37	        var dir = Path.GetDirectoryName(path);
38	        Assert.NotNull(dir);
39	        Directory.CreateDirectory(dir);
40	        File.WriteAllText(path, json);
41	    }
42	
43	    [Fact]
44	    public void MergePatch_preserves_sibling_sections()
45	    {
46	        SeedConfig("""
47	        {
48	          "gateway": { "url": "http://gw.example:7878", "token": "abc" },
49	          "screenshots": { "source_directory": "C:/old" }
50	        }
51	        """);
52	
53	        var patch = new JsonObject
54	        {
55	            ["screenshots"] = new JsonObject { ["source_directory"] = "/Users/username/Desktop" },
56	        };
57	        CcDirectorConfigService.MergePatch(patch);
58	
59	        var result = CcDirectorConfigService.ReadRaw();
60	        var screenshots = result["screenshots"];
61	        Assert.NotNull(screenshots);
62	        Assert.Equal("/Users/username/Desktop", (string?)screenshots["source_directory"]);
63	        // The untouched gateway block must survive intact.
64	        var gateway = result["gateway"];
65	        Assert.NotNull(gateway);
66	        Assert.Equal("http://gw.example:7878", (string?)gateway["url"]);
67	        Assert.Equal("abc", (string?)gateway["token"]);
68	    }
